with base as (select *, upper(txn_type) as txn_type_upper, coalesce(merchant, 'DIRECT') as merchant_filled from transactions where merchant is distinct from '7-Eleven'), with_gaps as (select *, case when txn_time - lag(txn_time) over (partition by merchant order by txn_time, id) > interval '90' day then 1 else 0 end as new_group_flag from base), islands as (select *, sum(new_group_flag) over (partition by merchant order by txn_time, id rows between unbounded preceding and current row) as session_no from with_gaps) select date_trunc('month', txn_time) as activity_month, merchant, percentile_approx(amount, 0.9) as amount_p90, count(case when txn_type = 'REFUND' then 1 end) as refund_count, grouping(date_trunc('month', txn_time)) as grouping_level from islands group by grouping sets ((date_trunc('month', txn_time), merchant), (date_trunc('month', txn_time)))
